/* @autogenerated */
import { firstValueFrom, of } from 'rxjs';
import { maskedDisplay, referenceDisplay } from './conflict-display';

describe('conflict-display', () => {
  const items: Record<string, { uid: string; name: string }> = {
    a: { uid: 'a', name: 'Alpha' },
    b: { uid: 'b', name: '' },
  };
  const repository = {
    retrieve: (key: string) => of(items[key]),
    displayProvider: () => ({ display: (item: { name: string }) => item.name }),
  };
  const display = referenceDisplay(repository);

  it('shows a reference by the label of its item', async () => {
    expect(await firstValueFrom(display({ $ref: 'a' }))).toBe('Alpha');
  });

  it('shows the key of a reference without item or without label', async () => {
    expect(await firstValueFrom(display({ $ref: 'missing' }))).toBe('missing');
    expect(await firstValueFrom(display({ $ref: 'b' }))).toBe('b');
  });

  it('shows nothing for an empty reference', async () => {
    expect(await firstValueFrom(display({ $ref: '' }))).toBe('');
  });

  it('joins the labels of a list of references', async () => {
    expect(await firstValueFrom(display([{ $ref: 'a' }, { $ref: 'missing' }]))).toBe('Alpha, missing');
    expect(await firstValueFrom(display([]))).toBe('');
  });

  it('masks the sensitive values', () => {
    expect(maskedDisplay()).toBe('••••••');
  });
});
